process.commandLine:
hp=${HTTPS_PROXY#http://}
p() { printf 'CONNECT %s HTTP/1.1\r\n\r\n' "$1" | nc -w 10 "${hp%:*}" "${hp##*:}" | head -n1 | cut -d' ' -f2; }
serve() { echo "MAPPED_$1" | timeout 120 nc -l -p "$1" > /tmp/r; echo "RECEIVED_$2=$(cat /tmp/r)"; }
echo PROXY=$(p 1.1.1.1:443)
nslookup example.com >/dev/null 2>&1 && echo DNS=RESOLVED || echo DNS=REFUSED
nc -z -w 3 1.1.1.1 443 && echo DIRECT=REACHED || echo DIRECT=BLOCKED
serve 8080 1
